assert all(not s or e for s,e in zip(shellable,extends))

# Independent recursive implementation of the definition in the question.
def canonical(fs):
    fs=set(fs)
    return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))

